import { z } from 'zod'
import { pikkuSessionlessFunc } from '#pikku'

export const EventsImportInput = z.object({
  calendarId: z.string().describe("Calendar identifier. To retrieve calendar IDs call the calendarList.list method. If you want to access the primary calendar of the currently logged in user, use the \"primary\" keyword."),
  alt: z.literal("json").optional().describe("Data format for the response."),
  fields: z.string().optional().describe("Selector specifying which fields to include in a partial response."),
  key: z.string().optional().describe("API key. Your API key identifies your project and provides you with API access, quota, and reports. Required unless you provide an OAuth 2.0 token."),
  oauth_token: z.string().optional().describe("OAuth 2.0 token for the current user."),
  prettyPrint: z.boolean().optional().describe("Returns response with indentations and line breaks."),
  quotaUser: z.string().optional().describe("An opaque string that represents a user for quota purposes. Must not exceed 40 characters."),
  userIp: z.string().optional().describe("Deprecated. Please use quotaUser instead."),
  conferenceDataVersion: z.number().int().min(0).max(1).optional().describe("Version number of conference data supported by the API client. Version 0 assumes no conference data support and ignores conference data in the event's body. Version 1 enables support for copying of ConferenceData as well as for creating new conferences using the createRequest field of conferenceData. The default is 0."),
  supportsAttachments: z.boolean().optional().describe("Whether API client performing operation supports event attachments. Optional. The default is False."),
  anyoneCanAddSelf: z.boolean().optional().default(false).describe("Whether anyone can invite themselves to the event (deprecated). Optional. The default is False."),
  attachments: z.array(z.object({
  fileId: z.string().optional().describe("ID of the attached file. Read-only.\nFor Google Drive files, this is the ID of the corresponding Files resource entry in the Drive API."),
  fileUrl: z.string().optional().describe("URL link to the attachment.\nFor adding Google Drive file attachments use the same format as in alternateLink property of the Files resource in the Drive API.\nRequired when adding an attachment."),
  iconLink: z.string().optional().describe("URL link to the attachment's icon. This field can only be modified for custom third-party attachments."),
  mimeType: z.string().optional().describe("Internet media type (MIME type) of the attachment."),
  title: z.string().optional().describe("Attachment title."),
})).optional().describe("File attachments for the event.\nIn order to modify attachments the supportsAttachments request parameter should be set to true.\nThere can be at most 25 attachments per event,"),
  attendees: z.array(z.object({
  additionalGuests: z.number().int().optional().default(0).describe("Number of additional guests. Optional. The default is 0."),
  comment: z.string().optional().describe("The attendee's response comment. Optional."),
  displayName: z.string().optional().describe("The attendee's name, if available. Optional."),
  email: z.string().optional().describe("The attendee's email address, if available. This field must be present when adding an attendee. It must be a valid email address as per RFC5322.\nRequired when adding an attendee."),
  id: z.string().optional().describe("The attendee's Profile ID, if available."),
  optional: z.boolean().optional().default(false).describe("Whether this is an optional attendee. Optional. The default is False."),
  organizer: z.boolean().optional().describe("Whether the attendee is the organizer of the event. Read-only. The default is False."),
  resource: z.boolean().optional().default(false).describe("Whether the attendee is a resource. Can only be set when the attendee is added to the event for the first time. Subsequent modifications are ignored. Optional. The default is False."),
  responseStatus: z.string().optional().describe("The attendee's response status. Possible values are:  \n- \"needsAction\" - The attendee has not responded to the invitation (recommended for new events). \n- \"declined\" - The attendee has declined the invitation. \n- \"tentative\" - The attendee has tentatively accepted the invitation. \n- \"accepted\" - The attendee has accepted the invitation.  Warning: If you add an event using the values declined, tentative, or accepted, attendees with the \"Add invitations to my calendar\" setting set to \"When I respond to invitation in email\" won't see an event on their calendar unless they choose to change their invitation response in the event invitation email."),
  self: z.boolean().optional().default(false).describe("Whether this entry represents the calendar on which this copy of the event appears. Read-only. The default is False."),
})).optional().describe("The attendees of the event. See the Events with attendees guide for more information on scheduling events with other calendar users. Service accounts need to use domain-wide delegation of authority to populate the attendee list."),
  attendeesOmitted: z.boolean().optional().default(false).describe("Whether attendees may have been omitted from the event's representation. When retrieving an event, this may be due to a restriction specified by the maxAttendee query parameter. When updating an event, this can be used to only update the participant's response. Optional. The default is False."),
  colorId: z.string().optional().describe("The color of the event. This is an ID referring to an entry in the event section of the colors definition (see the  colors endpoint). Optional."),
  conferenceData: z.object({
  conferenceId: z.string().optional().describe("The ID of the conference.\nCan be used by developers to keep track of conferences, should not be displayed to users.\nThe ID value is formed differently for each conference solution type:  \n- eventHangout: ID is not set. (This conference type is deprecated.)\n- eventNamedHangout: ID is the name of the Hangout. (This conference type is deprecated.)\n- hangoutsMeet: ID is the 10-letter meeting code, for example aaa-bbbb-ccc.\n- addOn: ID is defined by the third-party provider.  Optional."),
  conferenceSolution: z.object({
    iconUri: z.string().optional().describe("The user-visible icon for this solution."),
    key: z.object({
      type: z.string().optional().describe("The conference solution type.\nIf a client encounters an unfamiliar or empty type, it should still be able to display the entry points. However, it should disallow modifications.\nThe possible values are:  \n- \"eventHangout\" for Hangouts for consumers (deprecated; existing events may show this conference solution type but new conferences cannot be created)\n- \"eventNamedHangout\" for classic Hangouts for Google Workspace users (deprecated; existing events may show this conference solution type but new conferences cannot be created)\n- \"hangoutsMeet\" for Google Meet (http://meet.google.com)\n- \"addOn\" for 3P conference providers"),
    }).optional().describe("The key which can uniquely identify the conference solution for this event."),
    name: z.string().optional().describe("The user-visible name of this solution. Not localized."),
  }).optional().describe("The conference solution, such as Google Meet.\nUnset for a conference with a failed create request.\nEither conferenceSolution and at least one entryPoint, or createRequest is required."),
  createRequest: z.object({
    conferenceSolutionKey: z.object({
      type: z.string().optional().describe("The conference solution type.\nIf a client encounters an unfamiliar or empty type, it should still be able to display the entry points. However, it should disallow modifications.\nThe possible values are:  \n- \"eventHangout\" for Hangouts for consumers (deprecated; existing events may show this conference solution type but new conferences cannot be created)\n- \"eventNamedHangout\" for classic Hangouts for Google Workspace users (deprecated; existing events may show this conference solution type but new conferences cannot be created)\n- \"hangoutsMeet\" for Google Meet (http://meet.google.com)\n- \"addOn\" for 3P conference providers"),
    }).optional().describe("The conference solution, such as Hangouts or Google Meet."),
    requestId: z.string().optional().describe("The client-generated unique ID for this request.\nClients should regenerate this ID for every new request. If an ID provided is the same as for the previous request, the request is ignored."),
    status: z.object({
      statusCode: z.string().optional().describe("The current status of the conference create request. Read-only.\nThe possible values are:  \n- \"pending\": the conference create request is still being processed.\n- \"success\": the conference create request succeeded, the entry points are populated.\n- \"failure\": the conference create request failed, there are no entry points."),
    }).optional().describe("The status of the conference create request."),
  }).optional().describe("A request to generate a new conference and attach it to the event. The data is generated asynchronously. To see whether the data is present check the status field.\nEither conferenceSolution and at least one entryPoint, or createRequest is required."),
  entryPoints: z.array(z.object({
    accessCode: z.string().optional().describe("The access code to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed.\nOptional."),
    entryPointFeatures: z.array(z.string()).optional().describe("Features of the entry point, such as being toll or toll-free. One entry point can have multiple features. However, toll and toll-free cannot be both set on the same entry point."),
    entryPointType: z.string().optional().describe("The type of the conference entry point.\nPossible values are:  \n- \"video\" - joining a conference over HTTP. A conference can have zero or one video entry point.\n- \"phone\" - joining a conference by dialing a phone number. A conference can have zero or more phone entry points.\n- \"sip\" - joining a conference over SIP. A conference can have zero or one sip entry point.\n- \"more\" - further conference joining instructions, for example additional phone numbers. A conference can have zero or one more entry point. A conference with only a more entry point is not a valid conference."),
    label: z.string().optional().describe("The label for the URI. Visible to end users. Not localized. The maximum length is 512 characters.\nExamples:  \n- for video: meet.google.com/aaa-bbbb-ccc\n- for phone: +1 123 268 2601\n- for sip: 12345678@altostrat.com\n- for more: should not be filled  \nOptional."),
    meetingCode: z.string().optional().describe("The meeting code to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed.\nOptional."),
    passcode: z.string().optional().describe("The passcode to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed."),
    password: z.string().optional().describe("The password to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed.\nOptional."),
    pin: z.string().optional().describe("The PIN to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed.\nOptional."),
    regionCode: z.string().optional().describe("The CLDR/ISO 3166 region code for the country associated with this phone access. Example: \"SE\" for Sweden.\nCalendar backend will populate this field only for EntryPointType.PHONE."),
    uri: z.string().optional().describe("The URI of the entry point. The maximum length is 1300 characters.\nFormat:  \n- for video, http: or https: schema is required.\n- for phone, tel: schema is required. The URI should include the entire dial sequence (e.g., tel:+12345678900,,,123456789;1234).\n- for sip, sip: schema is required, e.g., sip:12345678@myprovider.com.\n- for more, http: or https: schema is required."),
  })).optional().describe("Information about individual conference entry points, such as URLs or phone numbers.\nAll of them must belong to the same conference.\nEither conferenceSolution and at least one entryPoint, or createRequest is required."),
  notes: z.string().optional().describe("Additional notes (such as instructions from the domain administrator, legal notices) to display to the user. Can contain HTML. The maximum length is 2048 characters. Optional."),
  parameters: z.object({
    addOnParameters: z.object({
      parameters: z.record(z.string(), z.string()).optional(),
    }).optional().describe("Additional add-on specific data."),
  }).optional().describe("Additional properties related to a conference. An example would be a solution-specific setting for enabling video streaming."),
  signature: z.string().optional().describe("The signature of the conference data.\nGenerated on server side.\nUnset for a conference with a failed create request.\nOptional for a conference with a pending create request."),
}).optional().describe("The conference-related information, such as details of a Google Meet conference. To create new conference details use the createRequest field. To persist your changes, remember to set the conferenceDataVersion request parameter to 1 for all event modification requests."),
  created: z.string().datetime().optional().describe("Creation time of the event (as a RFC3339 timestamp). Read-only."),
  creator: z.object({
  displayName: z.string().optional().describe("The creator's name, if available."),
  email: z.string().optional().describe("The creator's email address, if available."),
  id: z.string().optional().describe("The creator's Profile ID, if available."),
  self: z.boolean().optional().default(false).describe("Whether the creator corresponds to the calendar on which this copy of the event appears. Read-only. The default is False."),
}).optional().describe("The creator of the event. Read-only."),
  description: z.string().optional().describe("Description of the event. Can contain HTML. Optional."),
  end: z.object({
  date: z.string().date().optional().describe("The date, in the format \"yyyy-mm-dd\", if this is an all-day event."),
  dateTime: z.string().datetime().optional().describe("The time, as a combined date-time value (formatted according to RFC3339). A time zone offset is required unless a time zone is explicitly specified in timeZone."),
  timeZone: z.string().optional().describe("The time zone in which the time is specified. (Formatted as an IANA Time Zone Database name, e.g. \"Europe/Zurich\".) For recurring events this field is required and specifies the time zone in which the recurrence is expanded. For single events this field is optional and indicates a custom time zone for the event start/end."),
}).optional().describe("The (exclusive) end time of the event. For a recurring event, this is the end time of the first instance."),
  endTimeUnspecified: z.boolean().optional().default(false).describe("Whether the end time is actually unspecified. An end time is still provided for compatibility reasons, even if this attribute is set to True. The default is False."),
  etag: z.string().optional().describe("ETag of the resource."),
  eventType: z.string().optional().default("default").describe("Specific type of the event. Read-only. Possible values are:  \n- \"default\" - A regular event or not further specified. \n- \"outOfOffice\" - An out-of-office event. \n- \"focusTime\" - A focus-time event. \n- \"workingLocation\" - A working location event. Developer Preview."),
  extendedProperties: z.object({
  private: z.record(z.string(), z.string().describe("The name of the private property and the corresponding value.")).optional().describe("Properties that are private to the copy of the event that appears on this calendar."),
  shared: z.record(z.string(), z.string().describe("The name of the shared property and the corresponding value.")).optional().describe("Properties that are shared between copies of the event on other attendees' calendars."),
}).optional().describe("Extended properties of the event."),
  gadget: z.object({
  display: z.string().optional().describe("The gadget's display mode. Deprecated. Possible values are:  \n- \"icon\" - The gadget displays next to the event's title in the calendar view. \n- \"chip\" - The gadget displays when the event is clicked."),
  height: z.number().int().optional().describe("The gadget's height in pixels. The height must be an integer greater than 0. Optional. Deprecated."),
  iconLink: z.string().optional().describe("The gadget's icon URL. The URL scheme must be HTTPS. Deprecated."),
  link: z.string().optional().describe("The gadget's URL. The URL scheme must be HTTPS. Deprecated."),
  preferences: z.record(z.string(), z.string().describe("The preference name and corresponding value.")).optional().describe("Preferences."),
  title: z.string().optional().describe("The gadget's title. Deprecated."),
  type: z.string().optional().describe("The gadget's type. Deprecated."),
  width: z.number().int().optional().describe("The gadget's width in pixels. The width must be an integer greater than 0. Optional. Deprecated."),
}).optional().describe("A gadget that extends this event. Gadgets are deprecated; this structure is instead only used for returning birthday calendar metadata."),
  guestsCanInviteOthers: z.boolean().optional().default(true).describe("Whether attendees other than the organizer can invite others to the event. Optional. The default is True."),
  guestsCanModify: z.boolean().optional().default(false).describe("Whether attendees other than the organizer can modify the event. Optional. The default is False."),
  guestsCanSeeOtherGuests: z.boolean().optional().default(true).describe("Whether attendees other than the organizer can see who the event's attendees are. Optional. The default is True."),
  hangoutLink: z.string().optional().describe("An absolute link to the Google Hangout associated with this event. Read-only."),
  htmlLink: z.string().optional().describe("An absolute link to this event in the Google Calendar Web UI. Read-only."),
  iCalUID: z.string().optional().describe("Event unique identifier as defined in RFC5545. It is used to uniquely identify events accross calendaring systems and must be supplied when importing events via the import method.\nNote that the iCalUID and the id are not identical and only one of them should be supplied at event creation time. One difference in their semantics is that in recurring events, all occurrences of one event have different ids while they all share the same iCalUIDs. To retrieve an event using its iCalUID, call the events.list method using the iCalUID parameter. To retrieve an event using its id, call the events.get method."),
  id: z.string().optional().describe("Opaque identifier of the event. When creating new single or recurring events, you can specify their IDs. Provided IDs must follow these rules:  \n- characters allowed in the ID are those used in base32hex encoding, i.e. lowercase letters a-v and digits 0-9, see section 3.1.2 in RFC2938 \n- the length of the ID must be between 5 and 1024 characters \n- the ID must be unique per calendar  Due to the globally distributed nature of the system, we cannot guarantee that ID collisions will be detected at event creation time. To minimize the risk of collisions we recommend using an established UUID algorithm such as one described in RFC4122.\nIf you do not specify an ID, it will be automatically generated by the server.\nNote that the icalUID and the id are not identical and only one of them should be supplied at event creation time. One difference in their semantics is that in recurring events, all occurrences of one event have different ids while they all share the same icalUIDs."),
  kind: z.string().optional().default("calendar#event").describe("Type of the resource (\"calendar#event\")."),
  location: z.string().optional().describe("Geographic location of the event as free-form text. Optional."),
  locked: z.boolean().optional().default(false).describe("Whether this is a locked event copy where no changes can be made to the main event fields \"summary\", \"description\", \"location\", \"start\", \"end\" or \"recurrence\". The default is False. Read-Only."),
  organizer: z.object({
  displayName: z.string().optional().describe("The organizer's name, if available."),
  email: z.string().optional().describe("The organizer's email address, if available. It must be a valid email address as per RFC5322."),
  id: z.string().optional().describe("The organizer's Profile ID, if available."),
  self: z.boolean().optional().default(false).describe("Whether the organizer corresponds to the calendar on which this copy of the event appears. Read-only. The default is False."),
}).optional().describe("The organizer of the event. If the organizer is also an attendee, this is indicated with a separate entry in attendees with the organizer field set to True. To change the organizer, use the move operation. Read-only, except when importing an event."),
  originalStartTime: z.object({
  date: z.string().date().optional().describe("The date, in the format \"yyyy-mm-dd\", if this is an all-day event."),
  dateTime: z.string().datetime().optional().describe("The time, as a combined date-time value (formatted according to RFC3339). A time zone offset is required unless a time zone is explicitly specified in timeZone."),
  timeZone: z.string().optional().describe("The time zone in which the time is specified. (Formatted as an IANA Time Zone Database name, e.g. \"Europe/Zurich\".) For recurring events this field is required and specifies the time zone in which the recurrence is expanded. For single events this field is optional and indicates a custom time zone for the event start/end."),
}).optional().describe("For an instance of a recurring event, this is the time at which this event would start according to the recurrence data in the recurring event identified by recurringEventId. It uniquely identifies the instance within the recurring event series even if the instance was moved to a different time. Immutable."),
  privateCopy: z.boolean().optional().default(false).describe("If set to True, Event propagation is disabled. Note that it is not the same thing as Private event properties. Optional. Immutable. The default is False."),
  recurrence: z.array(z.string()).optional().describe("List of RRULE, EXRULE, RDATE and EXDATE lines for a recurring event, as specified in RFC5545. Note that DTSTART and DTEND lines are not allowed in this field; event start and end times are specified in the start and end fields. This field is omitted for single events or instances of recurring events."),
  recurringEventId: z.string().optional().describe("For an instance of a recurring event, this is the id of the recurring event to which this instance belongs. Immutable."),
  reminders: z.object({
  overrides: z.array(z.object({
    method: z.string().optional().describe("The method used by this reminder. Possible values are:  \n- \"email\" - Reminders are sent via email. \n- \"popup\" - Reminders are sent via a UI popup.  \nRequired when adding a reminder."),
    minutes: z.number().int().optional().describe("Number of minutes before the start of the event when the reminder should trigger. Valid values are between 0 and 40320 (4 weeks in minutes).\nRequired when adding a reminder."),
  })).optional().describe("If the event doesn't use the default reminders, this lists the reminders specific to the event, or, if not set, indicates that no reminders are set for this event. The maximum number of override reminders is 5."),
  useDefault: z.boolean().optional().describe("Whether the default reminders of the calendar apply to the event."),
}).optional().describe("Information about the event's reminders for the authenticated user."),
  sequence: z.number().int().optional().describe("Sequence number as per iCalendar."),
  source: z.object({
  title: z.string().optional().describe("Title of the source; for example a title of a web page or an email subject."),
  url: z.string().optional().describe("URL of the source pointing to a resource. The URL scheme must be HTTP or HTTPS."),
}).optional().describe("Source from which the event was created. For example, a web page, an email message or any document identifiable by an URL with HTTP or HTTPS scheme. Can only be seen or modified by the creator of the event."),
  start: z.object({
  date: z.string().date().optional().describe("The date, in the format \"yyyy-mm-dd\", if this is an all-day event."),
  dateTime: z.string().datetime().optional().describe("The time, as a combined date-time value (formatted according to RFC3339). A time zone offset is required unless a time zone is explicitly specified in timeZone."),
  timeZone: z.string().optional().describe("The time zone in which the time is specified. (Formatted as an IANA Time Zone Database name, e.g. \"Europe/Zurich\".) For recurring events this field is required and specifies the time zone in which the recurrence is expanded. For single events this field is optional and indicates a custom time zone for the event start/end."),
}).optional().describe("The (inclusive) start time of the event. For a recurring event, this is the start time of the first instance."),
  status: z.string().optional().describe("Status of the event. Optional. Possible values are:  \n- \"confirmed\" - The event is confirmed. This is the default status. \n- \"tentative\" - The event is tentatively confirmed. \n- \"cancelled\" - The event is cancelled (deleted). The list method returns cancelled events only on incremental sync (when syncToken or updatedMin are specified) or if the showDeleted flag is set to true. The get method always returns them.\nA cancelled status represents two different states depending on the event type:  \n- Cancelled exceptions of an uncancelled recurring event indicate that this instance should no longer be presented to the user. Clients should store these events for the lifetime of the parent recurring event.\nCancelled exceptions are only guaranteed to have values for the id, recurringEventId and originalStartTime fields populated. The other fields might be empty.  \n- All other cancelled events represent deleted events. Clients should remove their locally synced copies. Such cancelled events will eventually disappear, so do not rely on them being available indefinitely.\nDeleted events are only guaranteed to have the id field populated.   On the organizer's calendar, cancelled events continue to expose event details (summary, location, etc.) so that they can be restored (undeleted). Similarly, the events to which the user was invited and that they manually removed continue to provide details. However, incremental sync requests with showDeleted set to false will not return these details.\nIf an event changes its organizer (for example via the move operation) and the original organizer is not on the attendee list, it will leave behind a cancelled event where only the id field is guaranteed to be populated."),
  summary: z.string().optional().describe("Title of the event."),
  transparency: z.string().optional().default("opaque").describe("Whether the event blocks time on the calendar. Optional. Possible values are:  \n- \"opaque\" - Default value. The event does block time on the calendar. This is equivalent to setting Show me as to Busy in the Calendar UI. \n- \"transparent\" - The event does not block time on the calendar. This is equivalent to setting Show me as to Available in the Calendar UI."),
  updated: z.string().datetime().optional().describe("Last modification time of the event (as a RFC3339 timestamp). Read-only."),
  visibility: z.string().optional().default("default").describe("Visibility of the event. Optional. Possible values are:  \n- \"default\" - Uses the default visibility for events on the calendar. This is the default value. \n- \"public\" - The event is public and event details are visible to all readers of the calendar. \n- \"private\" - The event is private and only event attendees may view event details. \n- \"confidential\" - The event is private. This value is provided for compatibility reasons."),
  workingLocationProperties: z.object({
  customLocation: z.object({
    label: z.string().optional().describe("An optional extra label for additional information."),
  }).optional().describe("If present, specifies that the user is working from a custom location."),
  homeOffice: z.unknown().optional().describe("If present, specifies that the user is working at home."),
  officeLocation: z.object({
    buildingId: z.string().optional().describe("An optional building identifier. This should reference a building ID in the organization's Resources database."),
    deskId: z.string().optional().describe("An optional arbitrary desk identifier."),
    floorId: z.string().optional().describe("An optional arbitrary floor identifier."),
    floorSectionId: z.string().optional().describe("An optional arbitrary floor section identifier."),
    label: z.string().optional().describe("An optional extra label for additional information."),
  }).optional().describe("If present, specifies that the user is working from an office."),
}).optional().describe("Developer Preview: Working Location event data. Read-only."),
})

export const EventsImportOutput = z.object({
  anyoneCanAddSelf: z.boolean().optional().default(false).describe("Whether anyone can invite themselves to the event (deprecated). Optional. The default is False."),
  attachments: z.array(z.object({
    fileId: z.string().optional().describe("ID of the attached file. Read-only.\nFor Google Drive files, this is the ID of the corresponding Files resource entry in the Drive API."),
    fileUrl: z.string().optional().describe("URL link to the attachment.\nFor adding Google Drive file attachments use the same format as in alternateLink property of the Files resource in the Drive API.\nRequired when adding an attachment."),
    iconLink: z.string().optional().describe("URL link to the attachment's icon. This field can only be modified for custom third-party attachments."),
    mimeType: z.string().optional().describe("Internet media type (MIME type) of the attachment."),
    title: z.string().optional().describe("Attachment title."),
  })).optional().describe("File attachments for the event.\nIn order to modify attachments the supportsAttachments request parameter should be set to true.\nThere can be at most 25 attachments per event,"),
  attendees: z.array(z.object({
    additionalGuests: z.number().int().optional().default(0).describe("Number of additional guests. Optional. The default is 0."),
    comment: z.string().optional().describe("The attendee's response comment. Optional."),
    displayName: z.string().optional().describe("The attendee's name, if available. Optional."),
    email: z.string().optional().describe("The attendee's email address, if available. This field must be present when adding an attendee. It must be a valid email address as per RFC5322.\nRequired when adding an attendee."),
    id: z.string().optional().describe("The attendee's Profile ID, if available."),
    optional: z.boolean().optional().default(false).describe("Whether this is an optional attendee. Optional. The default is False."),
    organizer: z.boolean().optional().describe("Whether the attendee is the organizer of the event. Read-only. The default is False."),
    resource: z.boolean().optional().default(false).describe("Whether the attendee is a resource. Can only be set when the attendee is added to the event for the first time. Subsequent modifications are ignored. Optional. The default is False."),
    responseStatus: z.string().optional().describe("The attendee's response status. Possible values are:  \n- \"needsAction\" - The attendee has not responded to the invitation (recommended for new events). \n- \"declined\" - The attendee has declined the invitation. \n- \"tentative\" - The attendee has tentatively accepted the invitation. \n- \"accepted\" - The attendee has accepted the invitation.  Warning: If you add an event using the values declined, tentative, or accepted, attendees with the \"Add invitations to my calendar\" setting set to \"When I respond to invitation in email\" won't see an event on their calendar unless they choose to change their invitation response in the event invitation email."),
    self: z.boolean().optional().default(false).describe("Whether this entry represents the calendar on which this copy of the event appears. Read-only. The default is False."),
  })).optional().describe("The attendees of the event. See the Events with attendees guide for more information on scheduling events with other calendar users. Service accounts need to use domain-wide delegation of authority to populate the attendee list."),
  attendeesOmitted: z.boolean().optional().default(false).describe("Whether attendees may have been omitted from the event's representation. When retrieving an event, this may be due to a restriction specified by the maxAttendee query parameter. When updating an event, this can be used to only update the participant's response. Optional. The default is False."),
  colorId: z.string().optional().describe("The color of the event. This is an ID referring to an entry in the event section of the colors definition (see the  colors endpoint). Optional."),
  conferenceData: z.object({
    conferenceId: z.string().optional().describe("The ID of the conference.\nCan be used by developers to keep track of conferences, should not be displayed to users.\nThe ID value is formed differently for each conference solution type:  \n- eventHangout: ID is not set. (This conference type is deprecated.)\n- eventNamedHangout: ID is the name of the Hangout. (This conference type is deprecated.)\n- hangoutsMeet: ID is the 10-letter meeting code, for example aaa-bbbb-ccc.\n- addOn: ID is defined by the third-party provider.  Optional."),
    conferenceSolution: z.object({
      iconUri: z.string().optional().describe("The user-visible icon for this solution."),
      key: z.object({
        type: z.string().optional().describe("The conference solution type.\nIf a client encounters an unfamiliar or empty type, it should still be able to display the entry points. However, it should disallow modifications.\nThe possible values are:  \n- \"eventHangout\" for Hangouts for consumers (deprecated; existing events may show this conference solution type but new conferences cannot be created)\n- \"eventNamedHangout\" for classic Hangouts for Google Workspace users (deprecated; existing events may show this conference solution type but new conferences cannot be created)\n- \"hangoutsMeet\" for Google Meet (http://meet.google.com)\n- \"addOn\" for 3P conference providers"),
      }).optional().describe("The key which can uniquely identify the conference solution for this event."),
      name: z.string().optional().describe("The user-visible name of this solution. Not localized."),
    }).optional().describe("The conference solution, such as Google Meet.\nUnset for a conference with a failed create request.\nEither conferenceSolution and at least one entryPoint, or createRequest is required."),
    createRequest: z.object({
      conferenceSolutionKey: z.object({
        type: z.string().optional().describe("The conference solution type.\nIf a client encounters an unfamiliar or empty type, it should still be able to display the entry points. However, it should disallow modifications.\nThe possible values are:  \n- \"eventHangout\" for Hangouts for consumers (deprecated; existing events may show this conference solution type but new conferences cannot be created)\n- \"eventNamedHangout\" for classic Hangouts for Google Workspace users (deprecated; existing events may show this conference solution type but new conferences cannot be created)\n- \"hangoutsMeet\" for Google Meet (http://meet.google.com)\n- \"addOn\" for 3P conference providers"),
      }).optional().describe("The conference solution, such as Hangouts or Google Meet."),
      requestId: z.string().optional().describe("The client-generated unique ID for this request.\nClients should regenerate this ID for every new request. If an ID provided is the same as for the previous request, the request is ignored."),
      status: z.object({
        statusCode: z.string().optional().describe("The current status of the conference create request. Read-only.\nThe possible values are:  \n- \"pending\": the conference create request is still being processed.\n- \"success\": the conference create request succeeded, the entry points are populated.\n- \"failure\": the conference create request failed, there are no entry points."),
      }).optional().describe("The status of the conference create request."),
    }).optional().describe("A request to generate a new conference and attach it to the event. The data is generated asynchronously. To see whether the data is present check the status field.\nEither conferenceSolution and at least one entryPoint, or createRequest is required."),
    entryPoints: z.array(z.object({
      accessCode: z.string().optional().describe("The access code to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed.\nOptional."),
      entryPointFeatures: z.array(z.string()).optional().describe("Features of the entry point, such as being toll or toll-free. One entry point can have multiple features. However, toll and toll-free cannot be both set on the same entry point."),
      entryPointType: z.string().optional().describe("The type of the conference entry point.\nPossible values are:  \n- \"video\" - joining a conference over HTTP. A conference can have zero or one video entry point.\n- \"phone\" - joining a conference by dialing a phone number. A conference can have zero or more phone entry points.\n- \"sip\" - joining a conference over SIP. A conference can have zero or one sip entry point.\n- \"more\" - further conference joining instructions, for example additional phone numbers. A conference can have zero or one more entry point. A conference with only a more entry point is not a valid conference."),
      label: z.string().optional().describe("The label for the URI. Visible to end users. Not localized. The maximum length is 512 characters.\nExamples:  \n- for video: meet.google.com/aaa-bbbb-ccc\n- for phone: +1 123 268 2601\n- for sip: 12345678@altostrat.com\n- for more: should not be filled  \nOptional."),
      meetingCode: z.string().optional().describe("The meeting code to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed.\nOptional."),
      passcode: z.string().optional().describe("The passcode to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed."),
      password: z.string().optional().describe("The password to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed.\nOptional."),
      pin: z.string().optional().describe("The PIN to access the conference. The maximum length is 128 characters.\nWhen creating new conference data, populate only the subset of {meetingCode, accessCode, passcode, password, pin} fields that match the terminology that the conference provider uses. Only the populated fields should be displayed.\nOptional."),
      regionCode: z.string().optional().describe("The CLDR/ISO 3166 region code for the country associated with this phone access. Example: \"SE\" for Sweden.\nCalendar backend will populate this field only for EntryPointType.PHONE."),
      uri: z.string().optional().describe("The URI of the entry point. The maximum length is 1300 characters.\nFormat:  \n- for video, http: or https: schema is required.\n- for phone, tel: schema is required. The URI should include the entire dial sequence (e.g., tel:+12345678900,,,123456789;1234).\n- for sip, sip: schema is required, e.g., sip:12345678@myprovider.com.\n- for more, http: or https: schema is required."),
    })).optional().describe("Information about individual conference entry points, such as URLs or phone numbers.\nAll of them must belong to the same conference.\nEither conferenceSolution and at least one entryPoint, or createRequest is required."),
    notes: z.string().optional().describe("Additional notes (such as instructions from the domain administrator, legal notices) to display to the user. Can contain HTML. The maximum length is 2048 characters. Optional."),
    parameters: z.object({
      addOnParameters: z.object({
        parameters: z.record(z.string(), z.string()).optional(),
      }).optional().describe("Additional add-on specific data."),
    }).optional().describe("Additional properties related to a conference. An example would be a solution-specific setting for enabling video streaming."),
    signature: z.string().optional().describe("The signature of the conference data.\nGenerated on server side.\nUnset for a conference with a failed create request.\nOptional for a conference with a pending create request."),
  }).optional().describe("The conference-related information, such as details of a Google Meet conference. To create new conference details use the createRequest field. To persist your changes, remember to set the conferenceDataVersion request parameter to 1 for all event modification requests."),
  created: z.string().datetime().optional().describe("Creation time of the event (as a RFC3339 timestamp). Read-only."),
  creator: z.object({
    displayName: z.string().optional().describe("The creator's name, if available."),
    email: z.string().optional().describe("The creator's email address, if available."),
    id: z.string().optional().describe("The creator's Profile ID, if available."),
    self: z.boolean().optional().default(false).describe("Whether the creator corresponds to the calendar on which this copy of the event appears. Read-only. The default is False."),
  }).optional().describe("The creator of the event. Read-only."),
  description: z.string().optional().describe("Description of the event. Can contain HTML. Optional."),
  end: z.object({
    date: z.string().date().optional().describe("The date, in the format \"yyyy-mm-dd\", if this is an all-day event."),
    dateTime: z.string().datetime().optional().describe("The time, as a combined date-time value (formatted according to RFC3339). A time zone offset is required unless a time zone is explicitly specified in timeZone."),
    timeZone: z.string().optional().describe("The time zone in which the time is specified. (Formatted as an IANA Time Zone Database name, e.g. \"Europe/Zurich\".) For recurring events this field is required and specifies the time zone in which the recurrence is expanded. For single events this field is optional and indicates a custom time zone for the event start/end."),
  }).optional().describe("The (exclusive) end time of the event. For a recurring event, this is the end time of the first instance."),
  endTimeUnspecified: z.boolean().optional().default(false).describe("Whether the end time is actually unspecified. An end time is still provided for compatibility reasons, even if this attribute is set to True. The default is False."),
  etag: z.string().optional().describe("ETag of the resource."),
  eventType: z.string().optional().default("default").describe("Specific type of the event. Read-only. Possible values are:  \n- \"default\" - A regular event or not further specified. \n- \"outOfOffice\" - An out-of-office event. \n- \"focusTime\" - A focus-time event. \n- \"workingLocation\" - A working location event. Developer Preview."),
  extendedProperties: z.object({
    private: z.record(z.string(), z.string().describe("The name of the private property and the corresponding value.")).optional().describe("Properties that are private to the copy of the event that appears on this calendar."),
    shared: z.record(z.string(), z.string().describe("The name of the shared property and the corresponding value.")).optional().describe("Properties that are shared between copies of the event on other attendees' calendars."),
  }).optional().describe("Extended properties of the event."),
  gadget: z.object({
    display: z.string().optional().describe("The gadget's display mode. Deprecated. Possible values are:  \n- \"icon\" - The gadget displays next to the event's title in the calendar view. \n- \"chip\" - The gadget displays when the event is clicked."),
    height: z.number().int().optional().describe("The gadget's height in pixels. The height must be an integer greater than 0. Optional. Deprecated."),
    iconLink: z.string().optional().describe("The gadget's icon URL. The URL scheme must be HTTPS. Deprecated."),
    link: z.string().optional().describe("The gadget's URL. The URL scheme must be HTTPS. Deprecated."),
    preferences: z.record(z.string(), z.string().describe("The preference name and corresponding value.")).optional().describe("Preferences."),
    title: z.string().optional().describe("The gadget's title. Deprecated."),
    type: z.string().optional().describe("The gadget's type. Deprecated."),
    width: z.number().int().optional().describe("The gadget's width in pixels. The width must be an integer greater than 0. Optional. Deprecated."),
  }).optional().describe("A gadget that extends this event. Gadgets are deprecated; this structure is instead only used for returning birthday calendar metadata."),
  guestsCanInviteOthers: z.boolean().optional().default(true).describe("Whether attendees other than the organizer can invite others to the event. Optional. The default is True."),
  guestsCanModify: z.boolean().optional().default(false).describe("Whether attendees other than the organizer can modify the event. Optional. The default is False."),
  guestsCanSeeOtherGuests: z.boolean().optional().default(true).describe("Whether attendees other than the organizer can see who the event's attendees are. Optional. The default is True."),
  hangoutLink: z.string().optional().describe("An absolute link to the Google Hangout associated with this event. Read-only."),
  htmlLink: z.string().optional().describe("An absolute link to this event in the Google Calendar Web UI. Read-only."),
  iCalUID: z.string().optional().describe("Event unique identifier as defined in RFC5545. It is used to uniquely identify events accross calendaring systems and must be supplied when importing events via the import method.\nNote that the iCalUID and the id are not identical and only one of them should be supplied at event creation time. One difference in their semantics is that in recurring events, all occurrences of one event have different ids while they all share the same iCalUIDs. To retrieve an event using its iCalUID, call the events.list method using the iCalUID parameter. To retrieve an event using its id, call the events.get method."),
  id: z.string().optional().describe("Opaque identifier of the event. When creating new single or recurring events, you can specify their IDs. Provided IDs must follow these rules:  \n- characters allowed in the ID are those used in base32hex encoding, i.e. lowercase letters a-v and digits 0-9, see section 3.1.2 in RFC2938 \n- the length of the ID must be between 5 and 1024 characters \n- the ID must be unique per calendar  Due to the globally distributed nature of the system, we cannot guarantee that ID collisions will be detected at event creation time. To minimize the risk of collisions we recommend using an established UUID algorithm such as one described in RFC4122.\nIf you do not specify an ID, it will be automatically generated by the server.\nNote that the icalUID and the id are not identical and only one of them should be supplied at event creation time. One difference in their semantics is that in recurring events, all occurrences of one event have different ids while they all share the same icalUIDs."),
  kind: z.string().optional().default("calendar#event").describe("Type of the resource (\"calendar#event\")."),
  location: z.string().optional().describe("Geographic location of the event as free-form text. Optional."),
  locked: z.boolean().optional().default(false).describe("Whether this is a locked event copy where no changes can be made to the main event fields \"summary\", \"description\", \"location\", \"start\", \"end\" or \"recurrence\". The default is False. Read-Only."),
  organizer: z.object({
    displayName: z.string().optional().describe("The organizer's name, if available."),
    email: z.string().optional().describe("The organizer's email address, if available. It must be a valid email address as per RFC5322."),
    id: z.string().optional().describe("The organizer's Profile ID, if available."),
    self: z.boolean().optional().default(false).describe("Whether the organizer corresponds to the calendar on which this copy of the event appears. Read-only. The default is False."),
  }).optional().describe("The organizer of the event. If the organizer is also an attendee, this is indicated with a separate entry in attendees with the organizer field set to True. To change the organizer, use the move operation. Read-only, except when importing an event."),
  originalStartTime: z.object({
    date: z.string().date().optional().describe("The date, in the format \"yyyy-mm-dd\", if this is an all-day event."),
    dateTime: z.string().datetime().optional().describe("The time, as a combined date-time value (formatted according to RFC3339). A time zone offset is required unless a time zone is explicitly specified in timeZone."),
    timeZone: z.string().optional().describe("The time zone in which the time is specified. (Formatted as an IANA Time Zone Database name, e.g. \"Europe/Zurich\".) For recurring events this field is required and specifies the time zone in which the recurrence is expanded. For single events this field is optional and indicates a custom time zone for the event start/end."),
  }).optional().describe("For an instance of a recurring event, this is the time at which this event would start according to the recurrence data in the recurring event identified by recurringEventId. It uniquely identifies the instance within the recurring event series even if the instance was moved to a different time. Immutable."),
  privateCopy: z.boolean().optional().default(false).describe("If set to True, Event propagation is disabled. Note that it is not the same thing as Private event properties. Optional. Immutable. The default is False."),
  recurrence: z.array(z.string()).optional().describe("List of RRULE, EXRULE, RDATE and EXDATE lines for a recurring event, as specified in RFC5545. Note that DTSTART and DTEND lines are not allowed in this field; event start and end times are specified in the start and end fields. This field is omitted for single events or instances of recurring events."),
  recurringEventId: z.string().optional().describe("For an instance of a recurring event, this is the id of the recurring event to which this instance belongs. Immutable."),
  reminders: z.object({
    overrides: z.array(z.object({
      method: z.string().optional().describe("The method used by this reminder. Possible values are:  \n- \"email\" - Reminders are sent via email. \n- \"popup\" - Reminders are sent via a UI popup.  \nRequired when adding a reminder."),
      minutes: z.number().int().optional().describe("Number of minutes before the start of the event when the reminder should trigger. Valid values are between 0 and 40320 (4 weeks in minutes).\nRequired when adding a reminder."),
    })).optional().describe("If the event doesn't use the default reminders, this lists the reminders specific to the event, or, if not set, indicates that no reminders are set for this event. The maximum number of override reminders is 5."),
    useDefault: z.boolean().optional().describe("Whether the default reminders of the calendar apply to the event."),
  }).optional().describe("Information about the event's reminders for the authenticated user."),
  sequence: z.number().int().optional().describe("Sequence number as per iCalendar."),
  source: z.object({
    title: z.string().optional().describe("Title of the source; for example a title of a web page or an email subject."),
    url: z.string().optional().describe("URL of the source pointing to a resource. The URL scheme must be HTTP or HTTPS."),
  }).optional().describe("Source from which the event was created. For example, a web page, an email message or any document identifiable by an URL with HTTP or HTTPS scheme. Can only be seen or modified by the creator of the event."),
  start: z.object({
    date: z.string().date().optional().describe("The date, in the format \"yyyy-mm-dd\", if this is an all-day event."),
    dateTime: z.string().datetime().optional().describe("The time, as a combined date-time value (formatted according to RFC3339). A time zone offset is required unless a time zone is explicitly specified in timeZone."),
    timeZone: z.string().optional().describe("The time zone in which the time is specified. (Formatted as an IANA Time Zone Database name, e.g. \"Europe/Zurich\".) For recurring events this field is required and specifies the time zone in which the recurrence is expanded. For single events this field is optional and indicates a custom time zone for the event start/end."),
  }).optional().describe("The (inclusive) start time of the event. For a recurring event, this is the start time of the first instance."),
  status: z.string().optional().describe("Status of the event. Optional. Possible values are:  \n- \"confirmed\" - The event is confirmed. This is the default status. \n- \"tentative\" - The event is tentatively confirmed. \n- \"cancelled\" - The event is cancelled (deleted). The list method returns cancelled events only on incremental sync (when syncToken or updatedMin are specified) or if the showDeleted flag is set to true. The get method always returns them.\nA cancelled status represents two different states depending on the event type:  \n- Cancelled exceptions of an uncancelled recurring event indicate that this instance should no longer be presented to the user. Clients should store these events for the lifetime of the parent recurring event.\nCancelled exceptions are only guaranteed to have values for the id, recurringEventId and originalStartTime fields populated. The other fields might be empty.  \n- All other cancelled events represent deleted events. Clients should remove their locally synced copies. Such cancelled events will eventually disappear, so do not rely on them being available indefinitely.\nDeleted events are only guaranteed to have the id field populated.   On the organizer's calendar, cancelled events continue to expose event details (summary, location, etc.) so that they can be restored (undeleted). Similarly, the events to which the user was invited and that they manually removed continue to provide details. However, incremental sync requests with showDeleted set to false will not return these details.\nIf an event changes its organizer (for example via the move operation) and the original organizer is not on the attendee list, it will leave behind a cancelled event where only the id field is guaranteed to be populated."),
  summary: z.string().optional().describe("Title of the event."),
  transparency: z.string().optional().default("opaque").describe("Whether the event blocks time on the calendar. Optional. Possible values are:  \n- \"opaque\" - Default value. The event does block time on the calendar. This is equivalent to setting Show me as to Busy in the Calendar UI. \n- \"transparent\" - The event does not block time on the calendar. This is equivalent to setting Show me as to Available in the Calendar UI."),
  updated: z.string().datetime().optional().describe("Last modification time of the event (as a RFC3339 timestamp). Read-only."),
  visibility: z.string().optional().default("default").describe("Visibility of the event. Optional. Possible values are:  \n- \"default\" - Uses the default visibility for events on the calendar. This is the default value. \n- \"public\" - The event is public and event details are visible to all readers of the calendar. \n- \"private\" - The event is private and only event attendees may view event details. \n- \"confidential\" - The event is private. This value is provided for compatibility reasons."),
  workingLocationProperties: z.object({
    customLocation: z.object({
      label: z.string().optional().describe("An optional extra label for additional information."),
    }).optional().describe("If present, specifies that the user is working from a custom location."),
    homeOffice: z.unknown().optional().describe("If present, specifies that the user is working at home."),
    officeLocation: z.object({
      buildingId: z.string().optional().describe("An optional building identifier. This should reference a building ID in the organization's Resources database."),
      deskId: z.string().optional().describe("An optional arbitrary desk identifier."),
      floorId: z.string().optional().describe("An optional arbitrary floor identifier."),
      floorSectionId: z.string().optional().describe("An optional arbitrary floor section identifier."),
      label: z.string().optional().describe("An optional extra label for additional information."),
    }).optional().describe("If present, specifies that the user is working from an office."),
  }).optional().describe("Developer Preview: Working Location event data. Read-only."),
})

export const eventsImport = pikkuSessionlessFunc({
  description: "Imports an event. This operation is used to add a private copy of an existing event to a calendar.",
  input: EventsImportInput,
  output: EventsImportOutput,
  func: async ({ googleCalendar }, data) => {
    return googleCalendar.call("POST", "/calendars/{calendarId}/events/import", data) as any
  },
})
